package it.frociart.app;
import java.util.*;import java.nio.*;import java.nio.charset.*;

/** Bounded data-only parser/substitution for the Flowgorithm .fpgt format. */
final class FlowFpgtSyntax {
 static final int MAX_CHARACTERS=262144,MAX_BYTES=1048576,MAX_LINES=16384,MAX_SECTIONS=256,MAX_ROWS=8192,MAX_EXPANDED_CHARACTERS=2097152;
 static final class SyntaxError extends IllegalArgumentException {
  final int line;final String section,key;
  SyntaxError(int line,String section,String key,String detail){super("Modello .fpgt · riga "+line+(section.isEmpty()?"":" · ["+section+"]")+(key.isEmpty()?"":" · "+key)+": "+detail);this.line=line;this.section=section;this.key=key;}
 }
 static final class Row {
  final int line,indent;final String section,key,text;final List<String> conditions;
  Row(int line,String section,String key,String text,int indent,List<String> conditions){this.line=line;this.section=section;this.key=key;this.text=text;this.indent=indent;this.conditions=Collections.unmodifiableList(new ArrayList<>(conditions));}
  SyntaxError error(String detail){return new SyntaxError(line,section,key,detail);}
  boolean matches(Set<String> flags){return matches(flags,null);}
  boolean matches(Set<String> flags,Set<String> known){boolean matches=true;for(String condition:conditions){String flag=condition.charAt(0)=='~'?condition.substring(1):condition;if(known!=null&&!known.contains(flag))throw error("Flag non riconosciuto: «"+flag+"».");boolean present=flags!=null&&flags.contains(flag);if(present==(condition.charAt(0)=='~'))matches=false;}return matches;}
  String expand(Map<String,String> fields){StringBuilder result=new StringBuilder();for(int i=0;i<text.length();){char c=text.charAt(i++);if(c!='{'){append(result,String.valueOf(c));continue;}if(i<text.length()&&text.charAt(i)=='{'){i++;append(result,"{");continue;}int start=i-1,end=text.indexOf('}',i);if(end<0)throw error("Chiudi il campo con } oppure usa {{ per una parentesi letterale.");String name=normalize(text.substring(i,end));i=end+1;String value;if(name.equals("space"))value=" ";else if(name.equals("pipe"))value="|";else if(!nameToken(name))value=text.substring(start,end+1);else if(fields==null||!fields.containsKey(name))throw error("Campo non disponibile: {"+name+"}.");else value=fields.get(name);append(result,value==null?"":value);}return result.toString();}
  private void append(StringBuilder target,String value){if(value.length()>MAX_EXPANDED_CHARACTERS-target.length())throw error("Il testo generato supera 2 MiB di caratteri.");target.append(value);}
 }
 static final class Section {
  final String name;final int line;private final Map<String,List<Row>> keys=new LinkedHashMap<>();
  Section(String name,int line){this.name=name;this.line=line;}
  Set<String> keys(){return Collections.unmodifiableSet(keys.keySet());}
  List<Row> rows(String key){List<Row> rows=keys.get(normalize(key));return rows==null?Collections.emptyList():Collections.unmodifiableList(rows);}
  boolean has(String key){return keys.containsKey(normalize(key));}
  String value(String key){return value(key,null,null,null,null);}
  String value(String key,Set<String> flags,Map<String,String> fields,String fallback){return value(key,flags,fields,fallback,null);}
  String value(String key,Set<String> flags,Map<String,String> fields,String fallback,Set<String> known){for(Row row:rows(key))if(row.matches(flags,known))return fields==null?row.text:row.expand(fields);return fallback;}
  int number(String key,Set<String> flags,int fallback,Set<String> known){for(Row row:rows(key))if(row.matches(flags,known)){try{if(!row.text.matches("[+-]?[0-9]+"))throw new NumberFormatException();return Integer.parseInt(row.text);}catch(NumberFormatException e){throw row.error("Serve un valore intero valido.");}}return fallback;}
  void add(String key,Row row,boolean continuation){List<Row> rows=keys.get(key);if(rows==null){if(continuation)throw row.error("La continuazione non ha una chiave precedente.");rows=new ArrayList<>();keys.put(key,rows);}else if(!continuation)throw row.error("Chiave duplicata. Per un altro valore usa una riga che inizia con =.");rows.add(row);}
 }
 final String text,name,extension,direction;final boolean caseSensitive;private final Map<String,Section> sections;
 Set<String> sectionNames(){return Collections.unmodifiableSet(sections.keySet());}
 private FlowFpgtSyntax(String text,Map<String,Section> sections){this.text=text;this.sections=sections;Section language=require("language");name=language.value("name");String ext=language.value("extension");if(ext!=null&&ext.startsWith("."))ext=ext.substring(1);extension=ext;direction=language.value("direction",null,null,"left-to-right");if(name==null||trim(name).isEmpty()||name.length()>80||control(name))throw new SyntaxError(language.line,"language","name","Indica un nome di massimo 80 caratteri.");if(extension==null||!extension.matches("[A-Za-z][A-Za-z0-9]{0,15}"))throw new SyntaxError(language.line,"language","extension","Usa un’estensione di sole lettere e numeri, senza percorso.");if(!direction.equals("left-to-right")&&!direction.equals("right-to-left"))throw new SyntaxError(language.line,"language","direction","Usa left-to-right oppure right-to-left.");String sensitive=language.value("case sensitive",null,null,"true");if(!sensitive.equalsIgnoreCase("true")&&!sensitive.equalsIgnoreCase("false"))throw new SyntaxError(language.line,"language","case sensitive","Usa true oppure false.");caseSensitive=sensitive.equalsIgnoreCase("true");}
 private static boolean white(char c){int type=Character.getType(c);return c>=9&&c<=13||c==133||type==Character.SPACE_SEPARATOR||type==Character.LINE_SEPARATOR||type==Character.PARAGRAPH_SEPARATOR;}
 static String trim(String value){int start=0,end=value.length();while(start<end&&white(value.charAt(start)))start++;while(end>start&&white(value.charAt(end-1)))end--;return value.substring(start,end);}
 static String normalize(String value){return trim(value).toLowerCase(Locale.ROOT);}
 private static boolean nameToken(String name){if(name.isEmpty()||name.length()>80)return false;for(int i=0;i<name.length();i++){char c=name.charAt(i);if(!(c>='a'&&c<='z'||c>='0'&&c<='9'||c==' '||c=='-'||c=='_'))return false;}return true;}
 private static boolean control(String value){for(int i=0;i<value.length();i++)if(Character.isISOControl(value.charAt(i)))return true;return false;}
 Section find(String name){return sections.get(normalize(name));}
 Section require(String name){Section section=find(name);if(section==null)throw new SyntaxError(1,name,"","Manca questa sezione del modello.");return section;}
 static String decode(byte[] bytes){if(bytes==null||bytes.length>MAX_BYTES)throw new IllegalArgumentException("Il modello supera 1 MiB.");int skip=0;Charset charset=StandardCharsets.UTF_8;if(bytes.length>=2&&bytes[0]==(byte)0xff&&bytes[1]==(byte)0xfe){skip=2;charset=StandardCharsets.UTF_16LE;}else if(bytes.length>=2&&bytes[0]==(byte)0xfe&&bytes[1]==(byte)0xff){skip=2;charset=StandardCharsets.UTF_16BE;}else if(bytes.length>=3&&bytes[0]==(byte)0xef&&bytes[1]==(byte)0xbb&&bytes[2]==(byte)0xbf)skip=3;try{return charset.newDecoder().onMalformedInput(CodingErrorAction.REPORT).onUnmappableCharacter(CodingErrorAction.REPORT).decode(ByteBuffer.wrap(bytes,skip,bytes.length-skip)).toString();}catch(CharacterCodingException e){throw new IllegalArgumentException("Usa UTF-8 oppure UTF-16 con il contrassegno BOM. Il file non è stato modificato.");}}
 static FlowFpgtSyntax parse(String raw){
  if(raw==null||raw.length()>MAX_CHARACTERS)throw new IllegalArgumentException("Il modello supera 262144 caratteri.");int lineNo=1;for(int i=0;i<raw.length();i++){char c=raw.charAt(i);if(c=='\n')lineNo++;if(Character.isHighSurrogate(c)){if(++i>=raw.length()||!Character.isLowSurrogate(raw.charAt(i)))throw new SyntaxError(lineNo,"","","Carattere Unicode incompleto.");}else if(Character.isLowSurrogate(c)||Character.isISOControl(c)&&c!='\r'&&c!='\n'&&c!='\t')throw new SyntaxError(lineNo,"","","Carattere non valido nel modello.");}
  int bom=0;while(bom<raw.length()&&raw.charAt(bom)=='\uFEFF')bom++;String text=raw.substring(bom).replace("\r\n","\n").replace('\r','\n');String[] lines=text.split("\n",-1);if(lines.length>MAX_LINES)throw new IllegalArgumentException("Il modello supera 16384 righe.");Map<String,Section> sections=new LinkedHashMap<>();Section current=null;String previous=null;int count=0;
  for(int i=0;i<lines.length;i++){String s=trim(lines[i]);if(s.isEmpty()||s.charAt(0)==';')continue;if(s.charAt(0)=='['){if(s.charAt(s.length()-1)!=']')throw new SyntaxError(i+1,"","","Chiudi il nome della sezione con ].");String name=normalize(s.substring(1,s.length()-1));if(!nameToken(name))throw new SyntaxError(i+1,name,"","Nome della sezione non valido.");if(sections.size()>=MAX_SECTIONS)throw new SyntaxError(i+1,name,"","Troppe sezioni (massimo 256).");if(sections.containsKey(name))throw new SyntaxError(i+1,name,"","Sezione duplicata.");current=new Section(name,i+1);sections.put(name,current);previous=null;continue;}
   if(current==null)throw new SyntaxError(i+1,"","","Inserisci una sezione prima delle chiavi.");int equal=s.indexOf('=');if(equal<0)throw new SyntaxError(i+1,current.name,previous==null?"":previous,"Manca =. Per continuare un valore inizia la riga con =.");boolean continuation=equal==0;String key=continuation?previous:normalize(s.substring(0,equal));if(key==null||!nameToken(key))throw new SyntaxError(i+1,current.name,key==null?"":key,"Chiave non valida o continuazione senza chiave.");previous=key;String[] parts=s.substring(equal+1).split("\\|",-1);if(parts.length>3)throw new SyntaxError(i+1,current.name,key,"Per un pipe letterale usa {pipe}; i separatori ammessi sono due.");String value=trim(parts[0]);List<String> conditions=new ArrayList<>();if(parts.length>1&&!trim(parts[1]).isEmpty())for(String part:parts[1].split(",",-1)){String flag=normalize(part);if(flag.isEmpty())continue;String name=flag.startsWith("~")?flag.substring(1):flag;if(!nameToken(name)||name.contains(" ")||conditions.size()>=64)throw new SyntaxError(i+1,current.name,key,"Flag non valido o troppi flag sulla riga.");conditions.add(flag);}int indent=0;if(parts.length>2&&!trim(parts[2]).isEmpty()){try{if(!trim(parts[2]).matches("[+-]?[0-9]+"))throw new NumberFormatException();indent=Integer.parseInt(trim(parts[2]));}catch(NumberFormatException e){throw new SyntaxError(i+1,current.name,key,"Il rientro deve essere un intero da -32 a 32.");}if(indent< -32||indent>32)throw new SyntaxError(i+1,current.name,key,"Il rientro deve essere un intero da -32 a 32.");}if(++count>MAX_ROWS)throw new SyntaxError(i+1,current.name,key,"Il modello supera 8192 valori.");Row row=new Row(i+1,current.name,key,value,indent,conditions);validateFields(row);current.add(key,row,continuation);
  }return new FlowFpgtSyntax(text,sections);
 }
 private static void validateFields(Row row){if(!row.key.equals("text")&&!row.key.equals("normal")&&!row.key.equals("conflict")&&!row.key.equals("separator"))return;for(int i=0;i<row.text.length();i++){if(row.text.charAt(i)!='{')continue;if(i+1<row.text.length()&&row.text.charAt(i+1)=='{'){i++;continue;}int end=row.text.indexOf('}',i+1);if(end<0)throw row.error("Chiudi il campo con } oppure usa {{ per una parentesi letterale.");i=end;}}
}
